import numpy as npdef detection(E):    '''        Parameters    ----------    E : TYPE        DESCRIPTION.    Returns    -------    TYPE        DESCRIPTION.    '''    return np.abs(E)**2def determine_winner(E, det1=0, det2=-1):    '''        Parameters    ----------    E : TYPE        DESCRIPTION.    det1 : TYPE, optional        DESCRIPTION. The default is 0.    det2 : TYPE, optional        DESCRIPTION. The default is -1.    Returns    -------    int        DESCRIPTION.    '''    if E[det1] > E[det2]:        return 0    else:        return 1        